using System.Globalization;
using System.Security.Claims;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using MadaAcademy.Api.Modules.Operations;
using MadaAcademy.Api.Persistence;
using MadaAcademy.Api.Persistence.Entities;
using Microsoft.AspNetCore.Http;
using Microsoft.EntityFrameworkCore;

namespace MadaAcademy.Api.Modules.Scheduling;

public static class CourseGroupBulkImportEndpoints
{
    private const long MaxBytes = 5 * 1024 * 1024;
    private static readonly TimeSpan Lifetime = TimeSpan.FromHours(24);
    private const string TP = "BULK_IMPORT_COURSE_TEMPLATE_PREVIEW_CREATED", TC = "BULK_IMPORT_COURSE_TEMPLATE_COMMITTED";
    private const string GP = "BULK_IMPORT_GROUP_PREVIEW_CREATED", GC = "BULK_IMPORT_GROUP_COMMITTED";

    public static IEndpointRouteBuilder MapMadaCourseGroupBulkImportEndpoints(this IEndpointRouteBuilder endpoints)
    {
        var api = endpoints.MapGroup("/api/v1/imports").RequireAuthorization("staff");
        api.MapPost("/course-templates/csv/preview", PreviewTemplatesAsync); api.MapPost("/course-templates/commit", CommitTemplatesAsync);
        api.MapPost("/groups/csv/preview", PreviewGroupsAsync); api.MapPost("/groups/commit", CommitGroupsAsync);
        return endpoints;
    }

    private static async Task<IResult> PreviewTemplatesAsync(HttpRequest request, ClaimsPrincipal user, MadaDbContext db, CancellationToken ct)
    {
        if (!CanManage(user) || !Tenant(user, out var tenantId)) return Forbidden(); var upload = await Upload(request, ct); if (upload.Error is not null) return upload.Error; var rows = ParseTemplates(upload.Bytes!, out var errors); if (errors.Count > 0) return Validation(errors); if (rows.Length is 0 or > 1000) return Error(400, "ROW_LIMIT", "CSV must contain 1 to 1000 rows."); var existing = (await db.CourseTemplates.AsNoTracking().Where(x => x.TenantId == tenantId).Select(x => x.Name).ToListAsync(ct)).Select(x => x.Trim().ToUpperInvariant()).ToHashSet(); var seen = new HashSet<string>(); var preview = rows.Select((row, i) => { var e = new List<string>(); var name = row.Name.Trim(); var key = name.ToUpperInvariant(); if (name.Length is < 2 or > 160) e.Add("name must be between 2 and 160 characters."); if (row.TotalSessions < 1 || row.Duration <= 0 || row.Price < 0) e.Add("totalSessions, sessionDurationHours, and basePricePiastres are invalid."); if (!seen.Add(key) || existing.Contains(key)) e.Add("course template name already exists or appears twice."); return new TemplatePreviewRow(i + 1, name, row.Track.Trim().ToLowerInvariant(), row.Type.Trim().ToLowerInvariant(), row.AgeGroup.Trim(), row.Level.Trim().ToLowerInvariant(), row.TotalSessions, row.Duration, row.Price, e.Count == 0 ? "CREATE" : "REVIEW", e); }).ToArray(); return await Save(db, user, tenantId, TP, "BULK_IMPORT_COURSE_TEMPLATE_PREVIEW", preview, upload.Bytes!, upload.Name!, ct);
    }

    private static async Task<IResult> CommitTemplatesAsync(TemplateCommitRequest request, ClaimsPrincipal user, MadaDbContext db, CancellationToken ct)
    {
        if (!CanManage(user) || !Tenant(user, out var tenantId)) return Forbidden(); var stored = await Load<StoredTemplates>(db, tenantId, TP, request.PreviewId, ct); if (stored is null) return Error(404, "PREVIEW_NOT_FOUND", "Course template preview was not found."); var invalid = Guard(stored.Hash, stored.Source, request.PreviewHash, request.SourceFile); if (invalid is not null) return invalid; if (stored.Rows.Any(x => x.Action != "CREATE")) return Error(409, "PREVIEW_REQUIRES_REVIEW", "Resolve every REVIEW row before committing."); if (await Already(db, tenantId, TC, request.PreviewId, ct)) return Error(409, "PREVIEW_ALREADY_COMMITTED", "This preview has already been committed."); var names = (await db.CourseTemplates.Where(x => x.TenantId == tenantId).Select(x => x.Name).ToListAsync(ct)).Select(x => x.Trim().ToUpperInvariant()).ToHashSet(); if (stored.Rows.Any(x => names.Contains(x.Name.ToUpperInvariant()))) return Error(409, "PREVIEW_STALE", "A course template changed after preview."); var templates = stored.Rows.Select(x => new CourseTemplate { TenantId = tenantId, Name = x.Name, Track = x.Track, Type = x.Type, AgeGroup = x.AgeGroup, Level = x.Level, TotalSessions = x.TotalSessions, SessionDurationHours = x.Duration, BasePricePiastres = x.Price, Status = "DRAFT" }).ToArray(); db.CourseTemplates.AddRange(templates); db.AuditEvents.Add(new AuditEvent { ActorUserId = Actor(user), TenantId = tenantId, Action = TC, TargetType = "BULK_IMPORT_COURSE_TEMPLATE_PREVIEW", TargetId = request.PreviewId.ToString(), Reason = "Course template CSV committed after source identity and stale-data validation.", MetadataJson = JsonSerializer.Serialize(new { previewId = request.PreviewId, createdCount = templates.Length, state = "COMMITTED" }) }); await db.SaveChangesAsync(ct); return Results.Ok(new { data = new { request.PreviewId, createdCount = templates.Length, state = "COMMITTED", courseTemplateIds = templates.Select(x => x.Id).ToArray() } });
    }

    private static async Task<IResult> PreviewGroupsAsync(HttpRequest request, ClaimsPrincipal user, MadaDbContext db, CancellationToken ct)
    {
        if (!CanManage(user) || !Tenant(user, out var tenantId, out var branchScope)) return Forbidden(); var upload = await Upload(request, ct); if (upload.Error is not null) return upload.Error; var rows = ParseGroups(upload.Bytes!, out var errors); if (errors.Count > 0) return Validation(errors); if (rows.Length is 0 or > 1000) return Error(400, "ROW_LIMIT", "CSV must contain 1 to 1000 rows."); var branchIds = rows.Select(x => x.BranchId).Distinct().ToArray(); if (branchScope.HasValue && branchIds.Any(x => x != branchScope.Value)) return Error(403, "BRANCH_SCOPE_DENIED", "A branch-scoped user cannot import another branch."); var validBranches = await db.Branches.AsNoTracking().Where(x => x.TenantId == tenantId && x.Status == "ACTIVE" && branchIds.Contains(x.Id)).Select(x => x.Id).ToHashSetAsync(ct); var templateIds = rows.Select(x => x.TemplateId).Distinct().ToArray(); var templateSet = await db.CourseTemplates.AsNoTracking().Where(x => x.TenantId == tenantId && x.Status != "ARCHIVED" && templateIds.Contains(x.Id)).Select(x => x.Id).ToHashSetAsync(ct); var instructorIds = rows.Select(x => x.InstructorId).Distinct().ToArray(); var instructors = await db.Memberships.AsNoTracking().Where(x => x.TenantId == tenantId && x.Status == "ACTIVE" && instructorIds.Contains(x.UserAccountId) && (x.RoleCode == "R03_HEAD_INSTRUCTORS" || x.RoleCode == "R04_INSTRUCTOR")).Select(x => new { x.UserAccountId, x.BranchId }).ToListAsync(ct); var classrooms = await db.Classrooms.AsNoTracking().Where(x => x.Status == "AVAILABLE" && branchIds.Contains(x.BranchId)).Select(x => new { x.Id, x.BranchId, x.Capacity }).ToDictionaryAsync(x => x.Id, ct); var preview = rows.Select((row, i) => { var e = new List<string>(); if (!validBranches.Contains(row.BranchId)) e.Add("branchId is not an active branch in this academy."); if (!templateSet.Contains(row.TemplateId)) e.Add("courseTemplateId is not an active template in this academy."); var membership = instructors.FirstOrDefault(x => x.UserAccountId == row.InstructorId && (x.BranchId == null || x.BranchId == row.BranchId)); if (membership is null) e.Add("instructorId is not an active instructor in the selected branch."); if (!classrooms.TryGetValue(row.ClassroomId, out var room) || room.BranchId != row.BranchId) e.Add("classroomId is not an available classroom in the selected branch."); else if (row.MaxStudents < 1 || row.MaxStudents > room.Capacity) e.Add("maxStudents exceeds classroom capacity."); if (row.StartDate > row.EndDate || row.Days.Count == 0 || row.DurationMinutes is < 15 or > 480) e.Add("schedule values are invalid."); return new GroupPreviewRow(i + 1, row.BranchId, row.TemplateId, row.InstructorId, row.ClassroomId, row.StartDate, row.EndDate, row.Days, row.StartTime, row.DurationMinutes, row.MaxStudents, e.Count == 0 ? "CREATE" : "REVIEW", e); }).ToArray(); return await Save(db, user, tenantId, GP, "BULK_IMPORT_GROUP_PREVIEW", preview, upload.Bytes!, upload.Name!, ct);
    }

    private static async Task<IResult> CommitGroupsAsync(GroupCommitRequest request, ClaimsPrincipal user, MadaDbContext db, CancellationToken ct)
    {
        if (!CanManage(user) || !Tenant(user, out var tenantId, out var branchScope)) return Forbidden(); var stored = await Load<StoredGroups>(db, tenantId, GP, request.PreviewId, ct); if (stored is null) return Error(404, "PREVIEW_NOT_FOUND", "Group preview was not found."); var invalid = Guard(stored.Hash, stored.Source, request.PreviewHash, request.SourceFile); if (invalid is not null) return invalid; if (stored.Rows.Any(x => x.Action != "CREATE")) return Error(409, "PREVIEW_REQUIRES_REVIEW", "Resolve every REVIEW row before committing."); if (await Already(db, tenantId, GC, request.PreviewId, ct)) return Error(409, "PREVIEW_ALREADY_COMMITTED", "This preview has already been committed."); if (branchScope.HasValue && stored.Rows.Any(x => x.BranchId != branchScope.Value)) return Error(403, "BRANCH_SCOPE_DENIED", "A branch-scoped user cannot commit another branch."); var validBranches = await db.Branches.AsNoTracking().Where(x => x.TenantId == tenantId && x.Status == "ACTIVE").Select(x => x.Id).ToHashSetAsync(ct); var templateIds = stored.Rows.Select(x => x.TemplateId).ToArray(); var templates = await db.CourseTemplates.Where(x => x.TenantId == tenantId && templateIds.Contains(x.Id) && x.Status != "ARCHIVED").ToDictionaryAsync(x => x.Id, ct); var roomIds = stored.Rows.Select(x => x.ClassroomId).ToArray(); var rooms = await db.Classrooms.Where(x => roomIds.Contains(x.Id) && x.Status == "AVAILABLE").ToDictionaryAsync(x => x.Id, ct); var instructorIds = stored.Rows.Select(x => x.InstructorId).ToArray(); var activeInstructorIds = await db.Memberships.Where(x => x.TenantId == tenantId && x.Status == "ACTIVE" && instructorIds.Contains(x.UserAccountId) && (x.RoleCode == "R03_HEAD_INSTRUCTORS" || x.RoleCode == "R04_INSTRUCTOR")).Select(x => x.UserAccountId).ToHashSetAsync(ct); if (stored.Rows.Any(x => !validBranches.Contains(x.BranchId) || !templates.ContainsKey(x.TemplateId) || !rooms.ContainsKey(x.ClassroomId) || !activeInstructorIds.Contains(x.InstructorId) || rooms[x.ClassroomId].BranchId != x.BranchId)) return Error(409, "PREVIEW_STALE", "A group dependency changed after preview."); var offerings = new List<CourseOffering>(); var sessions = new List<AcademySession>(); foreach (var row in stored.Rows) { var offering = new CourseOffering { TenantId = tenantId, BranchId = row.BranchId, CourseTemplateId = row.TemplateId, InstructorId = row.InstructorId, ClassroomId = row.ClassroomId, StartDate = row.StartDate, EndDate = row.EndDate, WeeklyScheduleJson = JsonSerializer.Serialize(new { daysOfWeek = row.Days, startTime = row.StartTime, durationMinutes = row.DurationMinutes }), Status = "ACTIVE", MaxStudents = row.MaxStudents }; offerings.Add(offering); var number = 1; for (var day = row.StartDate; day <= row.EndDate; day = day.AddDays(1)) if (row.Days.Contains((int)day.DayOfWeek)) { var start = new DateTimeOffset(day.ToDateTime(row.StartTime), TimeSpan.Zero); sessions.Add(new AcademySession { TenantId = tenantId, BranchId = row.BranchId, CourseOfferingId = offering.Id, SessionNumber = number++, StartAt = start, EndAt = start.AddMinutes(row.DurationMinutes), InstructorId = row.InstructorId, ClassroomId = row.ClassroomId, Status = "SCHEDULED" }); } } if (sessions.Count == 0) return Error(409, "PREVIEW_STALE", "The group schedule produced no sessions."); db.CourseOfferings.AddRange(offerings); db.AcademySessions.AddRange(sessions); db.AuditEvents.Add(new AuditEvent { ActorUserId = Actor(user), TenantId = tenantId, BranchId = branchScope, Action = GC, TargetType = "BULK_IMPORT_GROUP_PREVIEW", TargetId = request.PreviewId.ToString(), Reason = "Group CSV committed with generated sessions after dependency validation.", MetadataJson = JsonSerializer.Serialize(new { previewId = request.PreviewId, createdGroups = offerings.Count, createdSessions = sessions.Count, state = "COMMITTED" }) }); await db.SaveChangesAsync(ct); return Results.Ok(new { data = new { request.PreviewId, createdGroups = offerings.Count, createdSessions = sessions.Count, state = "COMMITTED", groupIds = offerings.Select(x => x.Id).ToArray() } });
    }

    private static async Task<IResult> Save<T>(MadaDbContext db, ClaimsPrincipal user, Guid tenant, string action, string target, IReadOnlyList<T> rows, byte[] bytes, string name, CancellationToken ct) { var id = Guid.NewGuid(); var source = MakeSource(bytes, name); var hash = Hash(Encoding.UTF8.GetBytes(JsonSerializer.Serialize(rows))); var metadata = action == TP ? JsonSerializer.Serialize(new StoredTemplates(id, hash, "PREVIEWED", (IReadOnlyList<TemplatePreviewRow>)rows, source)) : JsonSerializer.Serialize(new StoredGroups(id, hash, "PREVIEWED", (IReadOnlyList<GroupPreviewRow>)rows, source)); db.AuditEvents.Add(new AuditEvent { ActorUserId = Actor(user), TenantId = tenant, BranchId = Guid.TryParse(user.FindFirstValue("branchId"), out var branch) ? branch : null, Action = action, TargetType = target, TargetId = id.ToString(), Reason = "CSV preview created; no records were written.", MetadataJson = metadata }); await db.SaveChangesAsync(ct); return Results.Ok(new { data = new { previewId = id, previewHash = hash, rows, sourceFile = source } }); }
    private static async Task<(byte[]? Bytes, string? Name, IResult? Error)> Upload(HttpRequest request, CancellationToken ct) { var form = await request.ReadFormAsync(ct); var file = form.Files.GetFile("file"); if (file is null || file.Length == 0 || file.Length > MaxBytes || !Path.GetExtension(file.FileName).Equals(".csv", StringComparison.OrdinalIgnoreCase)) return (null, null, Error(400, "FILE_INVALID", "A non-empty CSV file up to 5 MB with .csv extension is required.")); await using var input = file.OpenReadStream(); await using var ms = new MemoryStream(); await input.CopyToAsync(ms, ct); return (ms.ToArray(), Path.GetFileName(file.FileName).Trim(), null); }
    private static TemplateRow[] ParseTemplates(byte[] bytes, out List<string> errors) { errors = []; var lines = Lines(bytes); if (lines.Length < 2 || lines[0].ToLowerInvariant() != "name,track,type,agegroup,level,totalsessions,sessiondurationhours,basepricepiastres") { errors.Add("Header must be name,track,type,ageGroup,level,totalSessions,sessionDurationHours,basePricePiastres."); return []; } var rows = new List<TemplateRow>(); for (var i = 1; i < lines.Length; i++) { var c = lines[i].Split(','); if (c.Length != 8 || !int.TryParse(c[5], out var sessions) || !decimal.TryParse(c[6], NumberStyles.Number, CultureInfo.InvariantCulture, out var duration) || !int.TryParse(c[7], out var price)) { errors.Add($"Row {i + 1}: invalid template values."); continue; } rows.Add(new TemplateRow(c[0], c[1], c[2], c[3], c[4], sessions, duration, price)); } return rows.ToArray(); }
    private static GroupRow[] ParseGroups(byte[] bytes, out List<string> errors) { errors = []; var lines = Lines(bytes); if (lines.Length < 2 || lines[0].ToLowerInvariant() != "branchid,coursetemplateid,instructorid,classroomid,startdate,enddate,daysofweek,starttime,durationminutes,maxstudents") { errors.Add("Header must be branchId,courseTemplateId,instructorId,classroomId,startDate,endDate,daysOfWeek,startTime,durationMinutes,maxStudents."); return []; } var rows = new List<GroupRow>(); for (var i = 1; i < lines.Length; i++) { var c = lines[i].Split(','); if (c.Length != 10 || !Guid.TryParse(c[0], out var branch) || !Guid.TryParse(c[1], out var template) || !Guid.TryParse(c[2], out var instructor) || !Guid.TryParse(c[3], out var classroom) || !DateOnly.TryParseExact(c[4], "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out var start) || !DateOnly.TryParseExact(c[5], "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out var end) || !TimeOnly.TryParse(c[7], CultureInfo.InvariantCulture, out var time) || !int.TryParse(c[8], out var duration) || !int.TryParse(c[9], out var max)) { errors.Add($"Row {i + 1}: invalid group values."); continue; } var days = c[6].Split('|').Where(x => int.TryParse(x, out var d) && d is >= 0 and <= 6).Select(int.Parse).Distinct().ToArray(); rows.Add(new GroupRow(branch, template, instructor, classroom, start, end, days, time, duration, max)); } return rows.ToArray(); }
    private static string[] Lines(byte[] bytes) => Encoding.UTF8.GetString(bytes).TrimStart('\uFEFF').Split('\n').Select(x => x.TrimEnd('\r')).Where(x => !string.IsNullOrWhiteSpace(x)).ToArray(); private static string Hash(byte[] x) => Convert.ToHexString(SHA256.HashData(x)).ToLowerInvariant(); private static SourceFileIdentity MakeSource(byte[] bytes, string name) { var now = DateTimeOffset.UtcNow; return new SourceFileIdentity(name, bytes.Length, Hash(bytes), now, now.Add(Lifetime)); } private static IResult? Guard(string hash, SourceFileIdentity source, string suppliedHash, SourceFileIdentity? supplied) => source.ExpiresAt <= DateTimeOffset.UtcNow ? Error(410, "PREVIEW_EXPIRED", "The CSV preview expired.") : hash != suppliedHash ? Error(409, "PREVIEW_HASH_MISMATCH", "The preview hash does not match.") : supplied is null || source.Name != supplied.Name || source.Size != supplied.Size || source.Hash != supplied.Hash ? Error(409, "SOURCE_FILE_MISMATCH", "The source file identity does not match.") : null; private static async Task<T?> Load<T>(MadaDbContext db, Guid tenant, string action, Guid id, CancellationToken ct) { var item = await db.AuditEvents.SingleOrDefaultAsync(x => x.TenantId == tenant && x.Action == action && x.TargetId == id.ToString(), ct); return item?.MetadataJson is null ? default : JsonSerializer.Deserialize<T>(item.MetadataJson); } private static Task<bool> Already(MadaDbContext db, Guid tenant, string action, Guid id, CancellationToken ct) => db.AuditEvents.AnyAsync(x => x.TenantId == tenant && x.Action == action && x.TargetId == id.ToString(), ct); private static bool Tenant(ClaimsPrincipal user, out Guid tenant, out Guid? branch) { var ok = Guid.TryParse(user.FindFirstValue("tenantId"), out tenant); branch = Guid.TryParse(user.FindFirstValue("branchId"), out var parsed) ? parsed : null; return ok; } private static Guid? Actor(ClaimsPrincipal user) => Guid.TryParse(user.FindFirstValue("sub"), out var id) ? id : null; private static bool CanManage(ClaimsPrincipal user) => user.IsInRole("R01_ACADEMY_OWNER") || user.IsInRole("R02_BRANCH_MANAGER"); private static IResult Forbidden() => Error(403, "SCHEDULING_WRITE_FORBIDDEN", "This role cannot import scheduling data."); private static IResult Validation(List<string> e) => Results.ValidationProblem(new Dictionary<string, string[]> { ["file"] = e.ToArray() }); private static IResult Error(int s, string c, string m) => Results.Json(new { error = new { code = c, message = m } }, statusCode: s);
}
public sealed record TemplateRow(string Name, string Track, string Type, string AgeGroup, string Level, int TotalSessions, decimal Duration, int Price); public sealed record TemplatePreviewRow(int RowNumber, string Name, string Track, string Type, string AgeGroup, string Level, int TotalSessions, decimal Duration, int Price, string Action, IReadOnlyList<string> Errors); public sealed record StoredTemplates(Guid PreviewId, string Hash, string State, IReadOnlyList<TemplatePreviewRow> Rows, SourceFileIdentity Source); public sealed record TemplateCommitRequest(Guid PreviewId, string PreviewHash, SourceFileIdentity? SourceFile); public sealed record GroupRow(Guid BranchId, Guid TemplateId, Guid InstructorId, Guid ClassroomId, DateOnly StartDate, DateOnly EndDate, IReadOnlyList<int> Days, TimeOnly StartTime, int DurationMinutes, int MaxStudents); public sealed record GroupPreviewRow(int RowNumber, Guid BranchId, Guid TemplateId, Guid InstructorId, Guid ClassroomId, DateOnly StartDate, DateOnly EndDate, IReadOnlyList<int> Days, TimeOnly StartTime, int DurationMinutes, int MaxStudents, string Action, IReadOnlyList<string> Errors); public sealed record StoredGroups(Guid PreviewId, string Hash, string State, IReadOnlyList<GroupPreviewRow> Rows, SourceFileIdentity Source); public sealed record GroupCommitRequest(Guid PreviewId, string PreviewHash, SourceFileIdentity? SourceFile);
